templates.body:
{
"skeleton": {
	"spine": "4.3.23",
	"x": 0, "y": 0, "width": 0, "height": 0,
	"images": "./images/",
	"audio": null,
	"fps": {{project.fps}}
},
"bones": [
{{#each skeleton.bones}}	{ "name": "{{name}}"{{#if parent}}, "parent": "{{parent}}"{{/if}}{{#if length}}, "length": {{round length 4}}{{/if}}{{#if x}}, "x": {{round x 4}}{{/if}}{{#if y}}, "y": {{round y 4}}{{/if}}{{#if rotation}}, "rotation": {{round rotation 4}}{{/if}}{{#unless (eq scale_x 1.0)}}, "scaleX": {{round scale_x 4}}{{/unless}}{{#unless (eq scale_y 1.0)}}, "scaleY": {{round scale_y 4}}{{/unless}}{{#if shear_x}}, "shearX": {{round shear_x 4}}{{/if}}{{#if shear_y}}, "shearY": {{round shear_y 4}}{{/if}}{{#unless inherit_rotation}}, "inherit": "noRotationOrReflection"{{/unless}}{{#if color}}, "color": "{{hex color}}"{{/if}} }{{#unless @last}},{{/unless}}
{{/each}}],
"slots": [
{{#each skeleton.slots}}	{ "name": "{{name}}", "bone": "{{bone}}"{{#if attachment}}, "attachment": "{{attachment}}"{{/if}}{{#unless (eq (hex color) "ffffffff")}}, "color": "{{hex color}}"{{/unless}}{{#unless (eq blend "normal")}}, "blend": "{{blend}}"{{/unless}} }{{#unless @last}},{{/unless}}
{{/each}}],
{{#if skeleton.constraints}}"constraints": [
{{#each skeleton.constraints}}{{#if (eq type "ik")}}	{ "type": "ik", "name": "{{name}}", "target": "{{target}}", "bones": {{json bones}}{{#unless (eq mix 1.0)}}, "mix": {{round mix 4}}{{/unless}}{{#unless (eq bend_direction 1.0)}}, "bendPositive": false{{/unless}}{{#if softness}}, "softness": {{round softness 4}}{{/if}}{{#if stretch}}, "stretch": true{{/if}} }{{#if not_last}},{{/if}}
{{/if}}{{#if (eq type "transform")}}	{ "type": "transform", "name": "{{name}}", "source": "{{target}}", "bones": {{json bones}}{{#if offsets.x}}, "x": {{round offsets.x 4}}{{/if}}{{#if offsets.y}}, "y": {{round offsets.y 4}}{{/if}}{{#if offsets.rotation}}, "rotation": {{round offsets.rotation 4}}{{/if}}{{#if drives.any}}, "properties": { {{#if drives.rotate}}"rotate": { "to": { "rotate": { "max": 100 } } }{{/if}}{{#if drives.translate}}{{#if drives.rotate}}, {{/if}}"x": { "to": { "x": { "max": 100 } } }, "y": { "to": { "y": { "max": 100 } } }{{/if}}{{#if drives.scale}}{{#if (or drives.rotate drives.translate)}}, {{/if}}"scaleX": { "to": { "scaleX": {} } }, "scaleY": { "to": { "scaleY": {} } }{{/if}}{{#if drives.shear}}{{#if (or drives.rotate drives.translate drives.scale)}}, {{/if}}"shearY": { "to": { "shearY": { "max": 100 } } }{{/if}} }{{#if drives.rotate}}, "mixRotate": {{round mixes.rotate 4}}{{/if}}{{#if drives.translate_x}}, "mixX": {{round mixes.translate_x 4}}{{/if}}{{#if drives.translate_y}}, "mixY": {{round mixes.translate_y 4}}{{/if}}{{#if drives.scale_x}}, "mixScaleX": {{round mixes.scale_x 4}}{{/if}}{{#if drives.scale_y}}, "mixScaleY": {{round mixes.scale_y 4}}{{/if}}{{#if drives.shear_y}}, "mixShearY": {{round mixes.shear_y 4}}{{/if}}{{/if}} }{{#if not_last}},{{/if}}
{{/if}}{{#if (eq type "path")}}	{ "type": "path", "name": "{{name}}", "target": "{{slot}}", "bones": {{json bones}}{{#if path}}, "position": {{round path.position 4}}, "spacing": {{round path.spacing 4}}, "mixRotate": {{round path.mix_rotate 4}}, "mixX": {{round path.mix_translate 4}}{{/if}} }{{#if not_last}},{{/if}}
{{/if}}{{#if (eq type "physics")}}	{ "type": "physics", "name": "{{name}}", "bone": "{{#if bones.0}}{{bones.0}}{{/if}}"{{#if physics}}, "inertia": {{round physics.inertia 4}}, "strength": {{round physics.strength 4}}, "damping": {{round physics.damping 4}}, "mass": {{round physics.mass 4}}{{/if}}{{#if forces}}{{#if forces.gravity_y}}, "gravity": {{round forces.gravity_y 4}}{{/if}}{{#if forces.wind_x}}, "wind": {{round forces.wind_x 4}}{{/if}}{{/if}}{{#if channels}}{{#if channels.rotate}}, "rotate": 1{{/if}}{{#if channels.translate}}, "x": 1{{/if}}{{/if}} }{{#if not_last}},{{/if}}
{{/if}}{{/each}}],
{{/if}}"skins": [
{{#each skeleton.skins}}	{
		"name": "{{name}}",
		"attachments": {
{{#each slots}}			"{{slot}}": {
{{#each attachments}}				"{{name}}": {{#if (eq attachment.type "region")}}{ {{#if attachment.x}}"x": {{round attachment.x 4}}, {{/if}}{{#if attachment.y}}"y": {{round attachment.y 4}}, {{/if}}{{#if attachment.rotation}}"rotation": {{round attachment.rotation 4}}, {{/if}}{{#unless (eq attachment.scale_x 1.0)}}"scaleX": {{round attachment.scale_x 4}}, {{/unless}}{{#unless (eq attachment.scale_y 1.0)}}"scaleY": {{round attachment.scale_y 4}}, {{/unless}}"width": {{round attachment.width 0}}, "height": {{round attachment.height 0}} }{{/if}}{{#if (eq attachment.type "mesh")}}{ "type": "mesh", "uvs": {{numbers attachment.uvs 6}}, "triangles": {{json attachment.triangles}}, "vertices": {{numbers attachment.flat_vertices 4}}, "hull": {{attachment.hull}}{{#if attachment.edges_x2}}, "edges": {{json attachment.edges_x2}}{{/if}}, "width": {{round attachment.scaled_width 0}}, "height": {{round attachment.scaled_height 0}} }{{/if}}{{#if (eq attachment.type "bounding_box")}}{ "type": "boundingbox", "vertexCount": {{attachment.vertex_count}}, "vertices": {{json attachment.flat_vertices}} }{{/if}}{{#if (eq attachment.type "clipping")}}{ "type": "clipping"{{#if attachment.end_slot}}, "end": "{{attachment.end_slot}}"{{/if}}, "vertexCount": {{attachment.vertex_count}}, "vertices": {{json attachment.vertices}} }{{/if}}{{#if (eq attachment.type "point")}}{ "type": "point"{{#if attachment.x}}, "x": {{round attachment.x 4}}{{/if}}{{#if attachment.y}}, "y": {{round attachment.y 4}}{{/if}}{{#if attachment.rotation}}, "rotation": {{round attachment.rotation 4}}{{/if}} }{{/if}}{{#if (eq attachment.type "path")}}{ "type": "path", "closed": {{attachment.closed}}, "constantSpeed": {{attachment.constant_speed}}, "vertexCount": {{attachment.vertex_count}}, "vertices": {{json attachment.vertices}}, "lengths": [] }{{/if}}{{#unless @last}},{{/unless}}
{{/each}}			}{{#unless @last}},{{/unless}}
{{/each}}		}
	}{{#unless @last}},{{/unless}}
{{/each}}],
{{#if event_names}}"events": {
{{#each event_names}}	"{{this}}": {}{{#unless @last}},{{/unless}}
{{/each}}},
{{/if}}"animations": {
{{#each animations}}	"{{name}}": {
{{#if slots}}		"slots": {
{{#each slots}}			"{{name}}": { "{{#if (eq channel "color")}}rgba{{else}}{{channel}}{{/if}}": [
{{#each keys}}				{ {{#if time}}"time": {{round time 4}}{{#if (or name color)}}, {{/if}}{{/if}}{{#if color}}"color": "{{hex color}}"{{/if}}{{#if name}}"name": "{{name}}"{{/if}} }{{#unless @last}},{{/unless}}
{{/each}}			] }{{#unless @last}},{{/unless}}
{{/each}}		}{{#if (or bones ik_by_constraint transform deform events)}},{{/if}}
{{/if}}{{#if bones}}		"bones": {
{{#each bones}}			"{{name}}": { {{#if rotate}}"rotate": [
{{#each rotate}}				{ {{#if time}}"time": {{round time 4}}, {{/if}}"value": {{round value 4}}{{#if has_next}}{{#if points}}, "curve": {{numbers points 4}}{{else}}{{#if (eq curve "stepped")}}, "curve": "stepped"{{/if}}{{/if}}{{/if}} }{{#unless @last}},{{/unless}}
{{/each}}			]{{/if}}{{#if translate}}{{#if rotate}}, {{/if}}"translate": [
{{#each translate}}				{ {{#if time}}"time": {{round time 4}}, {{/if}}"x": {{round x 4}}, "y": {{round y 4}}{{#if has_next}}{{#if points}}, "curve": {{numbers points 4}}{{else}}{{#if (eq curve "stepped")}}, "curve": "stepped"{{/if}}{{/if}}{{/if}} }{{#unless @last}},{{/unless}}
{{/each}}			]{{/if}}{{#if scale}}{{#if (or rotate translate)}}, {{/if}}"scale": [
{{#each scale}}				{ {{#if time}}"time": {{round time 4}}, {{/if}}"x": {{round x 4}}, "y": {{round y 4}}{{#if has_next}}{{#if points}}, "curve": {{numbers points 4}}{{else}}{{#if (eq curve "stepped")}}, "curve": "stepped"{{/if}}{{/if}}{{/if}} }{{#unless @last}},{{/unless}}
{{/each}}			]{{/if}}{{#if shear}}{{#if (or rotate translate scale)}}, {{/if}}"shear": [
{{#each shear}}				{ {{#if time}}"time": {{round time 4}}, {{/if}}"x": {{round x 4}}, "y": {{round y 4}}{{#if has_next}}{{#if points}}, "curve": {{numbers points 4}}{{else}}{{#if (eq curve "stepped")}}, "curve": "stepped"{{/if}}{{/if}}{{/if}} }{{#unless @last}},{{/unless}}
{{/each}}			]{{/if}} }{{#unless @last}},{{/unless}}
{{/each}}		}{{#if (or ik_by_constraint transform deform events)}},{{/if}}
{{/if}}{{#if ik_by_constraint}}		"ik": {
{{#each ik_by_constraint}}			"{{constraint}}": [
{{#each keys}}				{ {{#if time}}"time": {{round time 4}}, {{/if}}"mix": {{#if (ne mix null)}}{{round mix 4}}{{else}}1{{/if}}{{#if softness}}, "softness": {{round softness 4}}{{/if}}{{#if bend_direction}}{{#unless (eq bend_direction 1.0)}}, "bendPositive": false{{/unless}}{{/if}}{{#if has_next}}{{#if points}}, "curve": {{numbers points 4}}{{else}}{{#if (eq curve "stepped")}}, "curve": "stepped"{{/if}}{{/if}}{{/if}} }{{#unless @last}},{{/unless}}
{{/each}}			]{{#unless @last}},{{/unless}}
{{/each}}		}{{#if (or transform deform events)}},{{/if}}
{{/if}}{{#if transform}}		"transform": {
{{#each transform}}			"{{constraint}}": [
{{#each keys}}				{ {{#if time}}"time": {{round time 4}}, {{/if}}"mixRotate": {{round rotate 4}}, "mixX": {{round translate_x 4}}, "mixY": {{round translate_y 4}}, "mixScaleX": {{round scale_x 4}}, "mixScaleY": {{round scale_y 4}}, "mixShearY": {{round shear_y 4}} }{{#unless @last}},{{/unless}}
{{/each}}			]{{#unless @last}},{{/unless}}
{{/each}}		}{{#if (or deform events)}},{{/if}}
{{/if}}{{#if deform}}		"attachments": {
			"{{../skeleton.default_skin}}": {
{{#each deform}}				"{{slot}}": { "{{attachment}}": { "deform": [
{{#each keys}}					{ {{#if time}}"time": {{round time 4}}, {{/if}}"vertices": {{numbers offsets 4}} }{{#unless @last}},{{/unless}}
{{/each}}				] } }{{#unless @last}},{{/unless}}
{{/each}}			}
		}{{#if events}},{{/if}}
{{/if}}{{#if events}}		"events": [
{{#each events}}			{ {{#if time}}"time": {{round time 4}}, {{/if}}"name": "{{name}}"{{#if int}}, "int": {{int}}{{/if}}{{#if float}}, "float": {{round float 4}}{{/if}}{{#if string}}, "string": "{{string}}"{{/if}} }{{#unless @last}},{{/unless}}
{{/each}}		]
{{/if}}	}{{#unless @last}},{{/unless}}
{{/each}}}
}
